// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Permanently delete an account while retaining its person
	// (DELETE /accounts/{accountId})
	DeleteAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// Get one account
	// (GET /accounts/{accountId})
	GetAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// Disable an account and revoke its sessions
	// (POST /accounts/{accountId}/disable)
	DisableAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// Enable an account
	// (POST /accounts/{accountId}/enable)
	EnableAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// Replace an account's email login identifier
	// (PUT /accounts/{accountId}/login-email)
	UpdateAccountLoginEmail(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// Administratively set an account password
	// (PUT /accounts/{accountId}/password)
	SetAccountPassword(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// Issue a one-time administrative password-reset link
	// (POST /accounts/{accountId}/password-reset)
	IssueAccountPasswordReset(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// Remove a role from an account
	// (DELETE /accounts/{accountId}/roles/{roleId})
	RemoveAccountRole(w http.ResponseWriter, r *http.Request, accountId AccountId, roleId RoleId)
	// Assign a role to an account
	// (PUT /accounts/{accountId}/roles/{roleId})
	AssignAccountRole(w http.ResponseWriter, r *http.Request, accountId AccountId, roleId RoleId)
	// List privacy-minimized audit events
	// (GET /audit-events)
	ListAuditEvents(w http.ResponseWriter, r *http.Request, params ListAuditEventsParams)
	// Start an email/password session
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Revoke the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Return the authenticated principal and current permissions
	// (GET /auth/me)
	GetCurrentUser(w http.ResponseWriter, r *http.Request)
	// Change the current account password
	// (PUT /auth/password)
	ChangeOwnPassword(w http.ResponseWriter, r *http.Request)
	// Redeem a one-time password-reset token
	// (POST /auth/password-reset/complete)
	CompletePasswordReset(w http.ResponseWriter, r *http.Request)
	// Report that the API process is running
	// (GET /health/live)
	GetLiveness(w http.ResponseWriter, r *http.Request)
	// Report whether required dependencies are ready
	// (GET /health/ready)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// Create an academic break
	// (POST /open-day-academic-breaks)
	CreateOpenDayAcademicBreak(w http.ResponseWriter, r *http.Request)
	// Delete an academic break
	// (DELETE /open-day-academic-breaks/{academicBreakId})
	DeleteOpenDayAcademicBreak(w http.ResponseWriter, r *http.Request, academicBreakId AcademicBreakId)
	// Update an academic break
	// (PATCH /open-day-academic-breaks/{academicBreakId})
	UpdateOpenDayAcademicBreak(w http.ResponseWriter, r *http.Request, academicBreakId AcademicBreakId)
	// List minimal roles usable for Open Day eligibility
	// (GET /open-day-eligibility-roles)
	ListOpenDayEligibilityRoles(w http.ResponseWriter, r *http.Request)
	// List Open Day periods visible to the caller
	// (GET /open-day-periods)
	ListOpenDayPeriods(w http.ResponseWriter, r *http.Request)
	// Create a draft Open Day period
	// (POST /open-day-periods)
	CreateOpenDayPeriod(w http.ResponseWriter, r *http.Request)
	// Get an Open Day period
	// (GET /open-day-periods/{periodId})
	GetOpenDayPeriod(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Update draft period metadata
	// (PATCH /open-day-periods/{periodId})
	UpdateOpenDayPeriod(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Archive a published period
	// (POST /open-day-periods/{periodId}/archive)
	ArchiveOpenDayPeriod(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Get holidays and academic breaks for a period
	// (GET /open-day-periods/{periodId}/calendar-context)
	GetOpenDayCalendarContext(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// List Open Days in a period
	// (GET /open-day-periods/{periodId}/open-days)
	ListOpenDays(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Create one Open Day
	// (POST /open-day-periods/{periodId}/open-days)
	CreateOpenDay(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Transition a draft period to open for staffing
	// (POST /open-day-periods/{periodId}/open-for-staffing)
	OpenOpenDayPeriodForStaffing(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Publish a staffing period
	// (POST /open-day-periods/{periodId}/publish)
	PublishOpenDayPeriod(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Return a staffing period to draft
	// (POST /open-day-periods/{periodId}/return-to-draft)
	ReturnOpenDayPeriodToDraft(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Unpublish a period and return it to staffing
	// (POST /open-day-periods/{periodId}/return-to-staffing)
	ReturnOpenDayPeriodToStaffing(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Atomically save a period schedule delta
	// (PUT /open-day-periods/{periodId}/schedule)
	SaveOpenDaySchedule(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Preview recurring Open Days without persisting them
	// (POST /open-day-periods/{periodId}/schedule/recurrence-preview)
	PreviewOpenDayRecurrence(w http.ResponseWriter, r *http.Request, periodId OpenDayPeriodId)
	// Search minimal eligible Person identities
	// (GET /open-day-staff-requirements/{requirementId}/eligible-people)
	ListOpenDayEligiblePeople(w http.ResponseWriter, r *http.Request, requirementId OpenDayRequirementId, params ListOpenDayEligiblePeopleParams)
	// Delete one Open Day from a draft period
	// (DELETE /open-days/{openDayId})
	DeleteOpenDay(w http.ResponseWriter, r *http.Request, openDayId OpenDayId)
	// Get one Open Day
	// (GET /open-days/{openDayId})
	GetOpenDay(w http.ResponseWriter, r *http.Request, openDayId OpenDayId)
	// Update one scheduled Open Day
	// (PATCH /open-days/{openDayId})
	UpdateOpenDay(w http.ResponseWriter, r *http.Request, openDayId OpenDayId)
	// Administratively assign an eligible Person
	// (POST /open-days/{openDayId}/assignments)
	AssignOpenDayPerson(w http.ResponseWriter, r *http.Request, openDayId OpenDayId)
	// Remove the current Person's assignment
	// (DELETE /open-days/{openDayId}/assignments/me)
	LeaveOpenDay(w http.ResponseWriter, r *http.Request, openDayId OpenDayId)
	// Assign the current Person to one staffing requirement
	// (PUT /open-days/{openDayId}/assignments/me)
	JoinOpenDay(w http.ResponseWriter, r *http.Request, openDayId OpenDayId)
	// Administratively remove an assignment
	// (DELETE /open-days/{openDayId}/assignments/{assignmentId})
	RemoveOpenDayAssignment(w http.ResponseWriter, r *http.Request, openDayId OpenDayId, assignmentId OpenDayAssignmentId)
	// Cancel a scheduled Open Day
	// (POST /open-days/{openDayId}/cancel)
	CancelOpenDay(w http.ResponseWriter, r *http.Request, openDayId OpenDayId)
	// List people for user administration
	// (GET /people)
	ListPeople(w http.ResponseWriter, r *http.Request, params ListPeopleParams)
	// Create a person
	// (POST /people)
	CreatePerson(w http.ResponseWriter, r *http.Request)
	// Permanently delete one person
	// (DELETE /people/{personId})
	DeletePerson(w http.ResponseWriter, r *http.Request, personId PersonId)
	// Get one person
	// (GET /people/{personId})
	GetPerson(w http.ResponseWriter, r *http.Request, personId PersonId)
	// Update one person
	// (PATCH /people/{personId})
	UpdatePerson(w http.ResponseWriter, r *http.Request, personId PersonId)
	// Create an account and email identity for a person
	// (POST /people/{personId}/account)
	CreatePersonAccount(w http.ResponseWriter, r *http.Request, personId PersonId)
	// List permissions registered by this application version
	// (GET /permissions)
	ListPermissions(w http.ResponseWriter, r *http.Request)
	// List the public Open Day schedule
	// (GET /public/open-days)
	ListPublicOpenDays(w http.ResponseWriter, r *http.Request)
	// Subscribe to the public Open Day iCalendar feed
	// (GET /public/open-days/calendar.ics)
	GetPublicOpenDaysCalendar(w http.ResponseWriter, r *http.Request)
	// List configured roles
	// (GET /roles)
	ListRoles(w http.ResponseWriter, r *http.Request, params ListRolesParams)
	// Create a configurable role
	// (POST /roles)
	CreateRole(w http.ResponseWriter, r *http.Request)
	// Delete a configurable role
	// (DELETE /roles/{roleId})
	DeleteRole(w http.ResponseWriter, r *http.Request, roleId RoleId)
	// Get one role
	// (GET /roles/{roleId})
	GetRole(w http.ResponseWriter, r *http.Request, roleId RoleId)
	// Update role metadata
	// (PATCH /roles/{roleId})
	UpdateRole(w http.ResponseWriter, r *http.Request, roleId RoleId)
	// Replace a configurable role's permissions
	// (PUT /roles/{roleId}/permissions)
	ReplaceRolePermissions(w http.ResponseWriter, r *http.Request, roleId RoleId)
}

